  { in: [1, 2, 3], exp: 6 },
  { in: [-2, 2], exp: 0 },
  { in: [], exp: 0 }
];

tests.forEach((t, i) => {
  const actual = solve(t.in);
  console.log(`Test ${i + 1}: ${actual === t.exp ? "PASS" : "FAIL"}`);
});

