// Two Sum Problem: Given array and target, find two indices whose values sum to target
function twoSum(nums, target) {
  const map = new Map(); // O(N) time, O(N) space
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (map.has(complement)) {
      return [map.get(complement), i];
    }
    map.set(nums[i], i);
  }
  return [];
}

console.log("Two sum result:", twoSum([2, 7, 11, 15], 9)); // [0, 1]

// Deduplicating an array in O(N) using Set
const rawList = [1, 2, 2, 3, 4, 4, 5];
const uniqueList = [...new Set(rawList)];
console.log("Unique elements:", uniqueList); // [1, 2, 3, 4, 5]

// Binary Search: O(log N) Time, O(1) Space
function binarySearch(arr, target) {
  let left = 0, right = arr.length - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) left = mid + 1;
    else right = mid - 1;
  }
  return -1;
}

console.log("Found at index:", binarySearch([10, 20, 30, 40, 50], 30)); // 2

// Palindrome Check Dry Run
function isPalindrome(str) {
  let left = 0, right = str.length - 1;
  while (left < right) {
    if (str[left] !== str[right]) return false;
    left++;
    right--;
  }
  return true;
}

console.log("racecar:", isPalindrome("racecar")); // true
console.log("hello:", isPalindrome("hello")); // false

